# TOOL-017: workspace cmake files generated by ibmw_cli verify the googletest
# archive hash and warn when a git dependency is not pinned to a commit sha.
# The rendered files run in cmake script mode with FetchContent stubbed out.
import shutil
import subprocess
import sys
from pathlib import Path

import pytest

CLI_DIR = Path(__file__).resolve().parents[2] / "ibmw_cli"
sys.path.insert(0, str(CLI_DIR))

from ibmw_cli.generator import GeneratorBase  # noqa: E402
from ibmw_cli.generator.workspace_generator import (  # noqa: E402
    DependsStdModuleExpandInfo, static_ws_template_infos, workspace_template_infos)

SHA = "0123456789abcdef0123456789abcdef01234567"
STUBS = """
function(FetchContent_Declare)
  message(STATUS "DECLARE ${ARGN}")
endfunction()
function(FetchContent_GetProperties name)
  set(${name}_POPULATED TRUE PARENT_SCOPE)
endfunction()
"""

pytestmark = pytest.mark.skipif(shutil.which("cmake") is None, reason="cmake not installed")


def _render(name, **context):
    infos = {info["template_name"]: info for info in workspace_template_infos + static_ws_template_infos}
    return GeneratorBase.get_template_environment(infos[name]).render(**context)


def _run(tmp_path, text, *defines):
    script = tmp_path / "case.cmake"
    script.write_text(STUBS + text.replace("include(FetchContent)", ""))
    result = subprocess.run(["cmake", *defines, "-P", str(script)], capture_output=True, text=True, timeout=60)
    assert result.returncode == 0, result.stderr
    return result.stdout + result.stderr


def _depend(git_tag):
    return DependsStdModuleExpandInfo(name="demo_dep", git_repository="https://example.invalid/demo.git",
                                      git_version=git_tag, std_depend_name="DemoDep")


def test_gtest_archive_hash_is_verified(tmp_path):
    out = _run(tmp_path, _render("get_gtest_cmake"))
    assert ("URL_HASH;SHA256=ad7fdba11ea011c1d925b3289cf4af2c66a352e18d4c7264392fead75e919363" in out), out


def test_ibmw_tag_warns_and_sha_override_is_quiet(tmp_path):
    text = _render("get_ibmw_cmake", workspace=type("W", (), {"ibmw_import_options": []})(), project_name="p")
    out = _run(tmp_path, text)
    assert "IBMW_GIT_TAG 'v0.1.0' is not a commit sha" in out and "GIT_TAG;v0.1.0" in out, out
    out = _run(tmp_path, text, f"-DIBMW_GIT_TAG={SHA}")
    assert "CMake Warning" not in out and f"GIT_TAG;{SHA}" in out, out


@pytest.mark.parametrize("git_tag, warns", [("v1.2.0", True), ("main", True), (SHA[:39], True),
                                            (SHA[:39] + "g", True), (SHA, False), (SHA.upper(), False)])
def test_depend_warns_unless_git_tag_is_a_sha(tmp_path, git_tag, warns):
    out = _run(tmp_path, _render("get_depends_cmake", depends_std_module=_depend(git_tag)))
    assert ("CMake Warning" in out) is warns, out
    assert f"GIT_TAG;{git_tag}" in out, out
